SELECT resource_uri, row_no, settlement_date, CASE WHEN n.upper_name IS NULL THEN receiver_name ELSE 'Без ЕИК и правна форма' END, is_person, receiver_iban, amount, currency, amount_eur, reason, reg_date, reg_no, pay_code, fin_code, fin_name, organization, primary_organization, primary_org_code, company_key, buyer_eik FROM tender.payment p LEFT JOIN tender.unnamed_name n ON n.upper_name = upper(p.receiver_name) AND p.company_key IS NULL AND NOT coalesce(p.is_person, false)
